CREATE OR REPLACE FUNCTION public.ci_research_panel_release_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'complete' THEN
    RAISE EXCEPTION 'completed Civica Index research panel releases are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.ci_research_panel_rows_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.ci_research_panel_releases
    WHERE id = COALESCE(OLD.release_id, NEW.release_id) AND status = 'complete'
  ) THEN
    RAISE EXCEPTION 'completed Civica Index research panel rows are immutable';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_capture_constitution_passage_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  before_row jsonb := to_jsonb(OLD);
  after_row jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(NEW) ELSE NULL END;
  evidence_id text := COALESCE(after_row->>'passage_id', before_row->>'passage_id');
BEGIN
  IF evidence_id IS NULL OR evidence_id !~ '^constitution-passage/sha256:[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'constitution passage history requires canonical passage_id';
  END IF;
  INSERT INTO research_evidence_history (
    entity_table, entity_id, operation, before, after, reason, actor_id
  ) VALUES (
    TG_TABLE_NAME, evidence_id, lower(TG_OP), before_row, after_row,
    lower(TG_OP) || '_retained_by_atl_009', current_user
  );
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_capture_research_evidence_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  before_row jsonb := to_jsonb(OLD);
  after_row jsonb := CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(NEW) ELSE NULL END;
  evidence_id text;
  evidence_actor text;
  evidence_reason text;
BEGIN
  evidence_id := COALESCE(after_row->>'id', before_row->>'id', md5(before_row::text));
  evidence_actor := COALESCE(
    NULLIF(after_row->>'reviewer_id', ''),
    NULLIF(after_row->>'actor_id', ''),
    NULLIF(before_row->>'reviewer_id', ''),
    current_user
  );
  evidence_reason := COALESCE(
    NULLIF(after_row->>'status_reason', ''),
    NULLIF(after_row->>'review_notes', ''),
    NULLIF(after_row->>'disposition', ''),
    NULLIF(after_row->>'classification_reason', ''),
    NULLIF(before_row->>'status_reason', ''),
    lower(TG_OP) || '_retained_by_dat_016'
  );

  INSERT INTO research_evidence_history (
    entity_table, entity_id, operation, before, after, reason, actor_id
  ) VALUES (
    TG_TABLE_NAME, evidence_id, lower(TG_OP), before_row, after_row,
    evidence_reason, evidence_actor
  );

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_ci_source_basket_version(source_ids jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
DECLARE source_lines text;
BEGIN
  IF jsonb_typeof(source_ids)<>'array' OR jsonb_array_length(source_ids)=0 THEN
    RETURN NULL;
  END IF;
  SELECT string_agg(source_id,E'\n' ORDER BY source_id) INTO source_lines
  FROM jsonb_array_elements_text(source_ids) AS source(source_id);
  RETURN 'source-basket/sha256:' || substr(encode(digest(source_lines,'sha256'),'hex'),1,16);
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_candidate_release_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_candidates integer; actual_winners integer; linked_winners integer;
BEGIN
  IF TG_OP <> 'UPDATE' OR OLD.completeness_status <> 'staging' OR NEW.completeness_status <> 'complete_candidates'
     OR (to_jsonb(OLD) - 'completeness_status') IS DISTINCT FROM (to_jsonb(NEW) - 'completeness_status') THEN
    RAISE EXCEPTION 'candidate release % is immutable except staging finalization', OLD.vintage_label;
  END IF;
  SELECT count(*)::int, count(*) FILTER (WHERE is_canonical_at_cut)::int INTO actual_candidates, actual_winners
    FROM country_fact_vintage_candidates WHERE vintage_label=NEW.vintage_label;
  SELECT count(*)::int INTO linked_winners FROM country_fact_vintages v
    JOIN country_fact_vintage_candidates c ON c.id=v.canonical_candidate_id AND c.vintage_label=v.vintage_label AND c.is_canonical_at_cut
    WHERE v.vintage_label=NEW.vintage_label;
  IF actual_candidates <> NEW.candidate_count OR actual_winners <> NEW.winner_count OR linked_winners <> NEW.winner_count THEN
    RAISE EXCEPTION 'candidate release % is incomplete: candidates %/%, winners %/%, linked %/%', NEW.vintage_label,
      actual_candidates, NEW.candidate_count, actual_winners, NEW.winner_count, linked_winners, NEW.winner_count;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_candidate_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE release_status text;
BEGIN
  SELECT completeness_status INTO release_status FROM country_fact_vintage_releases
    WHERE vintage_label=COALESCE(OLD.vintage_label, NEW.vintage_label);
  IF release_status <> 'staging' THEN
    RAISE EXCEPTION 'frozen candidate vintage % is immutable', COALESCE(OLD.vintage_label, NEW.vintage_label);
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_ci_release_header_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    IF NEW.status<>'staging' OR NEW.published_at IS NOT NULL THEN
      RAISE EXCEPTION 'Index release header % must be inserted as staging', NEW.id;
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status='published' THEN
    RAISE EXCEPTION 'published Index release header % is immutable', OLD.id;
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Index release header % cannot be deleted', OLD.id;
  END IF;
  IF (to_jsonb(OLD) - 'status' - 'published_at')
     IS DISTINCT FROM (to_jsonb(NEW) - 'status' - 'published_at') THEN
    RAISE EXCEPTION 'staged Index release header % identity is immutable', OLD.id;
  END IF;
  IF NEW.status='published' AND current_setting('civica.ci_release_publication',true) IS DISTINCT FROM NEW.id THEN
    RAISE EXCEPTION 'Index release % must be finalized through civica_publish_ci_release()', NEW.id;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_cron_job_lease_update_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_old_active boolean := OLD.lease_token IS NOT NULL;
  v_new_active boolean := NEW.lease_token IS NOT NULL;
BEGIN
  IF NEW.job_id IS DISTINCT FROM OLD.job_id OR NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'cron job lease identity cannot be rewritten';
  END IF;

  IF NEW.lease_fence = OLD.lease_fence THEN
    IF NOT v_old_active OR v_new_active THEN
      RAISE EXCEPTION 'a cron job lease may retain its fence only when released';
    END IF;
  ELSIF NEW.lease_fence = OLD.lease_fence + 1 THEN
    IF v_old_active OR NOT v_new_active THEN
      RAISE EXCEPTION 'a cron job lease fence may advance only on acquisition';
    END IF;
  ELSE
    RAISE EXCEPTION 'cron job lease fence must advance monotonically by one';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.civica_guard_published_ci_methodology()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM ci_index_releases WHERE methodology_version=OLD.id AND status='published') THEN
    RAISE EXCEPTION 'methodology % belongs to a published Index release and is immutable', OLD.id;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_published_ci_score_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE release_status text; affected_release_id text;
BEGIN
  affected_release_id := CASE WHEN TG_OP='DELETE' THEN OLD.release_id ELSE COALESCE(OLD.release_id,NEW.release_id) END;
  SELECT status INTO release_status FROM ci_index_releases
    WHERE id=affected_release_id;
  IF release_status='published' THEN
    RAISE EXCEPTION 'published Index release % is immutable', affected_release_id;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.civica_guard_published_pulse_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_run_id uuid; new_run_id uuid;
BEGIN
  IF TG_OP<>'INSERT' THEN old_run_id:=OLD.computation_run_id; END IF;
  IF TG_OP<>'DELETE' THEN new_run_id:=NEW.computation_run_id; END IF;
  IF EXISTS (
    SELECT 1 FROM pulse_score_publication_pointers pointer
    WHERE pointer.computation_run_id=old_run_id OR pointer.computation_run_id=new_run_id
  ) THEN
    RAISE EXCEPTION 'currently published Pulse score history is immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

